import { experiment } from '@caemble/core'
import { Solid } from './geometry'
import { Steel, Plastic, Composite } from './material'
export default experiment({
  lengthUnit: 'm',
  varsSchema: {},
  geometry: () => (
    <>
      <Solid
        id="plastic"
        size={[1, 0.3, 0.3]}
        position={[0.5, 0, 0]}
        materials={{ body: Plastic() }}
      />
      <Solid
        id="base"
        size={[0.6, 0.6, 0.2]}
        position={[2.5, 0, 0.1]}
        materials={{ body: Steel() }}
      />
      <Solid
        id="slider"
        size={[0.4, 0.4, 0.2]}
        position={[2.5, 0, 0.2999]}
        materials={{ body: Steel() }}
      />
      <Solid
        id="layer0"
        size={[1, 0.4, 0.2]}
        position={[3.5, 0, 0.1]}
        materials={{ body: Composite() }}
      />
      <Solid
        id="layer1"
        size={[1, 0.4, 0.2]}
        position={[3.5, 0, 0.3]}
        materials={{ body: Composite() }}
      />
    </>
  ),
  geometryGroup: {
    plastic: ['plastic'],
    contact: ['base', 'slider'],
    laminate: ['layer0', 'layer1'],
    upperLayer: ['layer1'],
  },
  surfaceGroup: {
    plasticFixed: ['plastic.shape/surface/0'],
    plasticLoaded: ['plastic.shape/surface/1'],
    baseFixed: ['base.shape/surface/4'],
    baseContact: ['base.shape/surface/5'],
    sliderGuide: [
      'slider.shape/surface/0',
      'slider.shape/surface/1',
      'slider.shape/surface/2',
      'slider.shape/surface/3',
    ],
    sliderContact: ['slider.shape/surface/4'],
    sliderLoaded: ['slider.shape/surface/5'],
    laminateFixed: ['layer0.shape/surface/0', 'layer1.shape/surface/0'],
    laminateLoaded: ['layer0.shape/surface/1', 'layer1.shape/surface/1'],
  },
  recordedData: {
    plastic_displacement: { task: 'plastic', output: 'displacement' },
    plastic_reaction: { task: 'plastic', output: 'reaction' },
    plastic_stress: { task: 'plastic', output: 'stress' },
    plastic_stressField: { task: 'plastic', output: 'stressField' },
    contact_displacement: { task: 'contact', output: 'displacement' },
    contact_reaction: { task: 'contact', output: 'reaction' },
    contact_stress: { task: 'contact', output: 'stress' },
    contact_stressField: { task: 'contact', output: 'stressField' },
    laminate_displacement: { task: 'laminate', output: 'displacement' },
    laminate_reaction: { task: 'laminate', output: 'reaction' },
    laminate_stress: { task: 'laminate', output: 'stress' },
    laminate_stressField: { task: 'laminate', output: 'stressField' },
  },
})

