files.tasks/contact.tsx:
import { Box, defineTask } from '@caemble/core'
export default defineTask({
  kernel: { name: 'structural-mechanics', version: '6.1.0' },
  lengthUnit: 'm',
  config: () => ({
    parameters: {
      analysis: 'static',
      geometricNonlinear: false,
      relativeTolerance: {
        dtype: 'float64',
        value: 1e-8,
        quantityKind: 'Dimensionless',
        unit: '1',
      },
      maxIterations: 40,
      spatialResolution: {
        dtype: 'float64',
        value: 0.18,
        quantityKind: 'Length',
        unit: 'm',
      },
    },
    initializations: [
      {
        methodId: 'fea.body',
        target: ['experiment.geometry.contact'],
        parameters: {},
      },
    ],
    boundaryConditions: [
      {
        methodId: 'fea.fixed',
        target: ['experiment.surface.baseFixed'],
        parameters: {
          components: {
            dtype: 'string',
            value: ['x', 'y', 'z'],
            axes: [{ length: 3 }],
          },
        },
      },
      {
        methodId: 'fea.fixed',
        target: ['experiment.surface.sliderGuide'],
        parameters: {
          components: {
            dtype: 'string',
            value: ['x', 'y'],
            axes: [{ length: 2 }],
          },
        },
      },
      {
        methodId: 'fea.surface-load',
        target: ['experiment.surface.sliderLoaded'],
        parameters: {
          force: {
            dtype: 'float64',
            value: [0, 0, -200],
            quantityKind: 'mechanics.ForceMagnitude',
            unit: 'N',
            axes: [{ length: 3 }],
          },
          moment: {
            dtype: 'float64',
            value: [0, 0, 0],
            quantityKind: 'mechanics.BendingMomentOfForce',
            unit: 'N.m',
            axes: [{ length: 3 }],
          },
          referencePoint: {
            dtype: 'float64',
            value: [2.5, 0, 0.3999],
            quantityKind: 'Length',
            unit: 'm',
            axes: [{ length: 3 }],
          },
        },
      },
      {
        methodId: 'fea.contact',
        target: [
          'experiment.surface.sliderContact',
          'experiment.surface.baseContact',
        ],
        parameters: {
          penalty: {
            dtype: 'float64',
            value: 1000000000,
            quantityKind: 'mechanics.NormalContactStiffness',
            unit: 'N.m-3',
          },
        },
      },
    ],
    outputs: [
      {
        methodId: 'fea.displacement',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'displacement',
      },
      {
        methodId: 'fea.reaction',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [1, 1, 1] },
        key: 'reaction',
      },
      {
        methodId: 'fea.stress-field',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'stress',
      },
      {
        methodId: 'fea.stress-field',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6] },
        key: 'stressField',
      },
    ],
    exports: [],
  }),
  geometry: () => (
    <Box
      id="output-grid"
      position={[2.5, 0, 0.19995000000000002]}
      size={[0.6005999999999996, 0.6005999999999999, 0.4002999]}
    />
  ),
  geometryGroup: { outputGrid: ['output-grid'] },
})

